  'Every event is for adults 18 and over unless you tick this. Accounts are for adults, so teens never sign up on their own.': 'Cada evento es para adultos de 18 años o más, a menos que marque esto. Las cuentas son para adultos, así que los adolescentes nunca se anotan solos.',
