  'Kids and teens can come and join in. Show it to anyone looking at the calendar, no account needed.': 'Los niños y adolescentes pueden venir y participar. Se muestra a cualquiera que mire el calendario, sin cuenta.',
  'Teens can help, with a parent or guardian': 'Los adolescentes pueden ayudar, con un padre, madre o tutor',
  'A parent or guardian signs up as an adult and brings them. You are not asked for any details about the teen.': 'Un padre, madre o tutor se anota como adulto y lo trae. No le pedimos ningún dato del adolescente.',
  'Sign-ups': 'Anotarse',
  'Let people sign up': 'Dejar que la gente se anote',
  "You'll see who signed up and any notes they leave.": 'Usted verá quién se anotó y las notas que dejen.',
  'What are people signing up for?': '¿Para qué se anota la gente?',
  'To help': 'Para ayudar',
  'Volunteers for a work day, drive, or shift.': 'Voluntarios para un día de trabajo, una colecta o un turno.',
  'To come': 'Para venir',
  'Neighbors letting you know they are coming, so you can plan food and seats.': 'Vecinos que le avisan que vienen, para que pueda planear la comida y los asientos.',
  'What do you still need people to bring? (optional)': '¿Qué falta que la gente traiga? (opcional)',
  'One thing per line. For example:\nNapkins\nPlates\nCups': 'Una cosa por línea. Por ejemplo:\nServilletas\nPlatos\nVasos',
  'Shows in its own box on the event page, above the sign-up button.': 'Se muestra en su propio cuadro en la página del evento, arriba del botón para anotarse.',
  'Anything else to add? (optional)': '¿Algo más que agregar? (opcional)',
  'Links, notes, or anything else. For example, a sign-up link.': 'Enlaces, notas, o lo que sea. Por ejemplo, un enlace para anotarse.',
  'Shows in its own box on the event page with no title above it. Whatever you type is all people see.': 'Se muestra en su propio cuadro en la página del evento, sin título arriba. Lo que escriba es todo lo que la gente ve.',
  'How many spots? (leave blank for no limit)': '¿Cuántos lugares? (déjelo en blanco para no poner límite)',
  'Post event': 'Publicar evento',

