  'Check your old and new email for confirmation links. Your login email updates once you confirm.': 'Revise su correo viejo y el nuevo para ver los enlaces de confirmación. Su correo para entrar cambia cuando usted confirme.',
  'Reset your account back to a plain Neighbor? This clears your Ambassador status, skills, availability, and any admin coverage area.': '¿Volver su cuenta a Vecino común? Esto borra su puesto de Embajador, sus habilidades, su horario y cualquier zona de administrador.',
