  '6-digit code': 'Código de 6 números',
  'Keep your phone safe. If you lose it, an admin can reset this for you after you email info@villagewithoutborders.org.': 'Cuide su teléfono. Si lo pierde, un administrador puede reiniciar esto después de que usted escriba a info@villagewithoutborders.org.',
