  'Your Devices': 'Sus aparatos',
  "Private messages are locked separately for each device. Open VWB once on each device you use so it can read new messages. A new device can't read messages sent before it was added.": 'Los mensajes privados se cierran aparte para cada aparato. Abra VWB una vez en cada aparato que use para que pueda leer los mensajes nuevos. Un aparato nuevo no puede leer mensajes enviados antes de agregarlo.',
