  'Sign out of all devices': 'Cerrar sesión en todos los aparatos',
  'Use this if you lost a device or think someone else got into your account. Other devices are signed out within about an hour. Your private message history stays on each device.': 'Use esto si perdió un aparato o cree que otra persona entró a su cuenta. La sesión en los otros aparatos se cierra en más o menos una hora. Sus mensajes privados se quedan en cada aparato.',
  'Delete My Account': 'Borrar mi cuenta',
  'Leave Village Without Borders for good.': 'Salir de Village Without Borders para siempre.',
  'Delete account': 'Borrar cuenta',
  'This removes your account and cannot be undone. Your profile, messages, and sign-ups go with it. If you lead a group that has other members, hand leadership to someone first.': 'Esto borra su cuenta y no se puede deshacer. Su perfil, sus mensajes y sus inscripciones se van con ella. Si dirige un grupo con otros miembros, pase el liderazgo a otra persona primero.',
  'Your password': 'Su contraseña',
  'Type DELETE to confirm': 'Escriba DELETE para confirmar',
  'Delete my account': 'Borrar mi cuenta',
  'Resetting...': 'Reiniciando...',
  'Reset to Neighbor': 'Volver a Vecino',
  'Make a new recovery key? Your old one will stop working.': '¿Hacer una clave de recuperación nueva? La vieja dejará de funcionar.',
  'Village Without Borders recovery key': 'Clave de recuperación de Village Without Borders',
  'Keep this somewhere private. Anyone who has it and can sign in to your account can read your private messages. VWB cannot recover it for you.': 'Guárdela en un lugar privado. Cualquiera que la tenga y pueda entrar a su cuenta puede leer sus mensajes privados. VWB no puede recuperarla por usted.',
  "That recovery key didn't work. Check it and try again.": 'Esa clave de recuperación no funcionó. Revísela e intente otra vez.',
  "There's no recovery key saved for this account yet.": 'Esta cuenta todavía no tiene una clave de recuperación guardada.',
  'Could not restore. Check your connection and try again.': 'No se pudo recuperar. Revise su conexión e intente otra vez.',
  'Recovery key': 'Clave de recuperación',
  "Your private messages are locked with a key that lives only on this device. If you clear your browser, lose your phone, or switch devices, old messages can't be opened. A recovery key lets you bring them back. We never see it, so we can't open your messages either.": 'Sus mensajes privados están cerrados con una clave que vive solo en este aparato. Si borra su navegador, pierde su teléfono o cambia de aparato, los mensajes viejos no se pueden abrir. Una clave de recuperación le deja traerlos de vuelta. Nosotros nunca la vemos, así que tampoco podemos abrir sus mensajes.',
  'Recovery key set up on {date}.': 'Clave de recuperación lista desde el {date}.',
  'Recovery key set up.': 'Clave de recuperación lista.',
  'You have not set up a recovery key yet.': 'Todavía no ha hecho una clave de recuperación.',
  'Working...': 'Trabajando...',
  'Make a new recovery key': 'Hacer una clave de recuperación nueva',
  'Make my recovery key': 'Hacer mi clave de recuperación',
  'I have a recovery key. Restore my messages.': 'Tengo una clave de recuperación. Recuperar mis mensajes.',
  'Your recovery key': 'Su clave de recuperación',
  'Restoring replaces the key on this device. Messages sent to this device since it lost its key stay locked.': 'Recuperar cambia la clave de este aparato. Los mensajes enviados a este aparato desde que perdió su clave siguen cerrados.',
  'Restoring...': 'Recuperando...',
  'Restore': 'Recuperar',
  'Save your recovery key': 'Guarde su clave de recuperación',
  "This is the only time we will show it. Write it down or save it somewhere private, like a password manager. We can't get it back for you.": 'Esta es la única vez que se la mostraremos. Escríbala o guárdela en un lugar privado, como un administrador de contraseñas. No podemos recuperarla por usted.',
