  // Messages hub
  'Talk with one neighbor, or with a few people you chose.': 'Hable con un vecino, o con algunas personas que usted eligió.',
  'Chats, villages, and neighbors, all in one place.': 'Chats, aldeas y vecinos, todo en un solo lugar.',
