  'Where to connect': 'Dónde conectar',
  'Open chat': 'Chat abierto',
  'Pick a chat on the left to read it here.': 'Elija un chat a la izquierda para leerlo aquí.',
  'Admin tools': 'Herramientas de administración',
  'Reports, removals, appeals, and group approvals.': 'Reportes, expulsiones, apelaciones y aprobación de grupos.',
  'Open admin tools': 'Abrir herramientas de administración',
  'Why so many kinds of chat?': '¿Por qué hay tantos tipos de chat?',
  'Different talks need different rooms. In one big chat, private things end up in front of strangers and it gets too noisy to follow. So VWB has rooms of different sizes.': 'Cada conversación necesita su propio cuarto. En un solo chat grande, las cosas privadas terminan frente a desconocidos y hay tanto ruido que no se puede seguir. Por eso VWB tiene cuartos de distintos tamaños.',
  'The bigger the room, the less you share.': 'Entre más grande el cuarto, menos comparte.',
  "Not sure? Pick the smallest room that fits. You can always share more later, but you can't take back what a crowd has seen.": '¿No está seguro? Elija el cuarto más pequeño que sirva. Siempre puede compartir más después, pero no puede quitar lo que mucha gente ya vio.',
  'Use it for:': 'Úselo para:',
  'Safety:': 'Seguridad:',
  'Smallest room at the top, biggest at the bottom. Tap a room to learn more. In every chat you can mute, leave, block, or report.': 'El cuarto más pequeño arriba, el más grande abajo. Toque un cuarto para saber más. En todos los chats puede silenciar, salir, bloquear o reportar.',
  'Close this guide': 'Cerrar esta guía',
  'Private message': 'Mensaje privado',
  'You and one other person.': 'Usted y otra persona.',
