  'Scrambled. Only the two of you can read it.': 'Cifrado. Solo ustedes dos lo pueden leer.',
  'Cottage Chat': 'Chat de la casita',
  'A few people you choose.': 'Unas pocas personas que usted elige.',
  'Family, close friends, or a small crew you trust.': 'Familia, amigos cercanos o un equipo pequeño de confianza.',
