  'Campfire': 'Fogata',
  'A team inside a village, group, or crew.': 'Un equipo dentro de una aldea, un grupo o un equipo de emergencia.',
  'Planning and working together: a church, a nonprofit, a cleanup crew. A smaller Campfire can branch off for one job, like "Saturday food drive drivers", so the main one stays calm.': 'Planear y trabajar juntos: una iglesia, una organización sin fines de lucro, un equipo de limpieza. Una Fogata más pequeña puede salir para un solo trabajo, como "Choferes de la colecta de comida del sábado", para que la principal se mantenga tranquila.',
  'Members only. You ask to join or someone adds you.': 'Solo para miembros. Usted pide unirse o alguien le agrega.',
  'Village chat': 'Chat de la aldea',
  'Neighbors whose home village it is, plus guests.': 'Los vecinos que viven en esa aldea, más invitados.',
  'Lost pets, road closures, saying hello, local news.': 'Mascotas perdidas, calles cerradas, saludar, noticias del lugar.',
  'Members only. Neighbors in its zip codes can join, and others come as guests. Keep private details out. Messages delete after 30 days.': 'Solo para miembros. Los vecinos de sus códigos postales pueden unirse, y otros vienen como invitados. No ponga detalles privados. Los mensajes se borran después de 30 días.',
