  'Waiting to be confirmed': 'Esperando confirmación',
  'Waiting to be confirmed.': 'Esperando confirmación.',
  'When 2 neighbors say they see it too, or a Hope Ambassador checks it, the Response Camp chat opens and nearby emergency crews are called.': 'Cuando 2 vecinos digan que también lo ven, o un Embajador de Esperanza lo revise, se abre el chat del Campamento de respuesta y se llama a los equipos de emergencia cercanos.',
  'I see this too: go to the list to say so': 'Yo también lo veo: ir a la lista para decirlo',
  'Verify this emergency': 'Confirmar esta emergencia',
  'Waiting to be checked.': 'Esperando revisión.',
  'You are a Hope Ambassador or VWB admin. If this is real, verify it to open the Response Camp and call the crews that cover this village.': 'Usted es Embajador de Esperanza o administrador de VWB. Si es real, confírmela para abrir el Campamento de respuesta y llamar a los equipos que cubren esta aldea.',
  'Verifying...': 'Confirmando...',
