  'Both sides confirmed. Open Tasks to say how it went, and to vouch for them if it went well.': 'Los dos confirmaron. Abra Tareas para decir cómo le fue, y para responder por la otra persona si salió bien.',
  "Tap \"Mark my part complete\" when you're done too.": 'Toque "Marcar mi parte como hecha" cuando usted también termine.',
