  // Profile
  'Leave all your village chats? You can join again any time.': '¿Salir de todos los chats de sus aldeas? Puede volver a unirse cuando quiera.',
  'Name is required.': 'Hace falta un nombre.',
  'Could not save profile. Try again.': 'No se pudo guardar el perfil. Intente otra vez.',
  'Profile saved.': 'Perfil guardado.',
  'Pick at least one skill you can help with.': 'Elija por lo menos una habilidad con la que pueda ayudar.',
  'Tell us how you know this community, or who can vouch for you.': 'Díganos cómo conoce esta comunidad, o quién puede responder por usted.',
  'Something went wrong sending your application. Try again.': 'Algo salió mal al enviar su solicitud. Intente otra vez.',
  'Application sent. An admin will look it over, and you will get a notification when there is an answer.': 'Solicitud enviada. Un administrador la revisará, y usted recibirá un aviso cuando haya una respuesta.',
  'Could not save your response. Try again.': 'No se pudo guardar su respuesta. Intente otra vez.',
  'Add your zip code to your profile first.': 'Primero ponga su código postal en su perfil.',
  'Add a region name first.': 'Primero ponga el nombre de una región.',
  'Tap Use my zip code area first.': 'Primero toque Usar la zona de mi código postal.',
  'Could not save. Try again.': 'No se pudo guardar. Intente otra vez.',
  'Your coverage area is set. Reports can now route to you.': 'Su zona de cobertura está lista. Ahora los reportes le pueden llegar a usted.',
  'Avatar saved!': '¡Avatar guardado!',
  'Change avatar': 'Cambiar avatar',
  'I am in a village chat': 'Estoy en un chat de aldea',
  'Turn this on to find village chats near your zip code. Turn it off to leave all of them.': 'Actívelo para buscar chats de aldea cerca de su código postal. Apáguelo para salir de todos.',
  'Find or start a village chat': 'Buscar o empezar un chat de aldea',
  'Skills': 'Habilidades',
  'None yet': 'Ninguna todavía',
  'Help radius': 'Distancia para ayudar',
