  'Ambassador Details': 'Datos de Embajador',
  'Availability': 'Disponibilidad',
  'About me': 'Sobre mí',
  'Status': 'Estado',
  'Your application is in': 'Su solicitud fue recibida',
  'An admin will look it over and let you know. Until then you can ask for help, offer help, and look around.': 'Un administrador la revisará y le avisará. Mientras tanto puede pedir ayuda, ofrecer ayuda y mirar la app.',
  'Become a Hope Ambassador': 'Hágase Embajador de Esperanza',
  'Hope Ambassadors are neighbors who volunteer their time and skills to help others in the community. An admin looks over each application so this stays a community people can trust.': 'Los Embajadores de Esperanza son vecinos que dan su tiempo y lo que saben hacer para ayudar a otros en la comunidad. Un administrador revisa cada solicitud para que esta siga siendo una comunidad de confianza.',
  'Your last application was not approved. You can apply again, or reach out to an admin.': 'Su última solicitud no fue aprobada. Puede pedirlo otra vez, o hablar con un administrador.',
  "Apply": "Solicitar",
  'Post in Announcements and join the Ambassadors board. Apply above': 'Publique en Anuncios y únase al tablero de Embajadores. Pídalo arriba',
  'Hope Ambassador Application': 'Solicitud para Embajador de Esperanza',
  'Tell us a little about how you can help.': 'Cuéntenos un poco cómo puede ayudar.',
  'No need to get it perfect. Pick at least one skill to start. You can change your skills anytime by editing your Profile.': 'No tiene que quedar perfecto. Elija por lo menos una habilidad para empezar. Puede cambiar sus habilidades cuando quiera desde su perfil.',
  'When are you usually available?': '¿Cuándo suele estar disponible?',
  'Anything else you want neighbors to know?': '¿Algo más que quiera que sepan sus vecinos?',
  'Your experience, why you want to help, or anything else': 'Su experiencia, por qué quiere ayudar, o cualquier otra cosa',
  "The Village Square holds Announcements, the Ambassadors board, and your village chat. Leave this unchecked and you can still read it anytime, you just won't get a push for every message. Change this later from Village Square's settings.": 'En la Plaza de la aldea están los Anuncios, el tablero de Embajadores y el chat de su aldea. Si deja esto sin marcar, igual puede leerla cuando quiera, solo que no le llegará un aviso por cada mensaje. Puede cambiarlo después en los ajustes de la Plaza de la aldea.',
  'Set up your coverage area': 'Ponga su zona de cobertura',
  "Emergency dispute reviews (a false alarm or duplicate flag) route to the nearest admin, so add your area and use your zip code area to catch the ones near you. Reports about a person or message go to every admin right away, wherever they're located.": 'Las revisiones de emergencias en duda (una falsa alarma o un reporte repetido) van al administrador más cercano, así que ponga su zona y use la zona de su código postal para recibir las que están cerca. Los reportes sobre una persona o un mensaje les llegan enseguida a todos los administradores, estén donde estén.',
  'What area do you cover? (towns or counties)': '¿Qué zona cubre? (pueblos o condados)',
  'Using your zip code area': 'Usando la zona de su código postal',
  'Use my zip code area': 'Usar la zona de mi código postal',
  'Become an admin for your village': 'Hágase administrador de su aldea',
  'Admins help coordinate responses in their region and keep the community safe.': 'Los administradores ayudan a organizar respuestas en su región y a cuidar la comunidad.',
  "See if you're ready": 'Vea si está listo',
  "You've been invited to become an Admin": 'Le invitaron a ser administrador',
  "An admin thinks you'd be a good fit to help coordinate responses in your area. Accepting sends this back to them for final confirmation.": 'Un administrador cree que usted sería bueno para ayudar a organizar respuestas en su zona. Si acepta, se le devuelve a esa persona para la confirmación final.',
  'Your admin application is under review': 'Su solicitud para administrador está en revisión',
