  'e.g., 30736': 'por ejemplo, 30736',
  "Used to show neighbors near you. Only you and VWB admins can see it. Leave it blank if you'd rather not say, and the app will ask when it needs an area.": 'Sirve para mostrarle vecinos cerca. Solo usted y los administradores de VWB lo pueden ver. Déjelo en blanco si prefiere no decirlo, y la app le preguntará cuando necesite una zona.',
  'Neighborhood or area': 'Barrio o zona',
  "Enter your zip code above and we'll list the towns near you.": 'Escriba su código postal arriba y le mostraremos los pueblos cercanos.',
  'Somewhere else (type it)': 'Otro lugar (escríbalo)',
