  'Your neighborhood or subdivision': 'Su barrio o colonia',
  "\"{name}\" isn't one of the towns near this zip code. Pick a town from the list, or keep it if it's right.": '"{name}" no es uno de los pueblos cerca de este código postal. Elija un pueblo de la lista, o déjelo si está bien.',
  'Towns near {zip}. Only you and VWB admins see your zip. The area shows on posts you make.': 'Pueblos cerca de {zip}. Solo usted y los administradores de VWB ven su código postal. La zona aparece en lo que usted publica.',
