  // Village and cottage scene
  "Local village chat": "Chat de la aldea de su zona",
  "Join a village chat?": "¿Unirse a un chat de la aldea?",
  "Village chats are for neighbors in your area. We use your zip code to find them. You can join more than one, and you can leave any time from your Profile.": "Los chats de la aldea son para los vecinos de su zona. Usamos su código postal para encontrarlos. Puede unirse a más de uno, y puede salirse cuando quiera desde su Perfil.",
  "Yes, join": "Sí, unirme",
  "No thanks": "No, gracias",
  "Here is your day.": "Este es su día.",
  "1 thing needs you today.": "Hoy 1 cosa le espera.",
  "{n} things need you today.": "Hoy {n} cosas le esperan.",
  "You're new here": "Usted es nuevo aquí",
  "Right now you can ask for help, offer to help on requests, join your village, and reply to anyone who messages you.": "Por ahora puede pedir ayuda, ofrecer ayuda en los pedidos, unirse a su aldea y contestar a quien le escriba.",
  "Once a neighbor vouches for you, or you finish a task with someone, you can also message people first, post offers, and start chats and emergency crews. It keeps VWB safe from fake accounts.": "Cuando un vecino responda por usted, o termine una tarea con alguien, también podrá escribir primero a la gente, publicar ofrecimientos y empezar chats y equipos de emergencia. Así VWB se protege de cuentas falsas.",
  "Floods, storms, fires, outages": "Inundaciones, tormentas, incendios, apagones",
  "Floods, storms, fires, and outages that hit many neighbors": "Inundaciones, tormentas, incendios y apagones que afectan a muchos vecinos",
  "Share a skill, an hour, or a ride, and we'll match you with neighbors nearby who need one. An admin looks over each application.": "Comparta algo que sabe hacer, una hora o un viaje, y le pondremos en contacto con vecinos cerca que lo necesiten. Un administrador revisa cada solicitud.",
  "Install VWB": "Instalar VWB",
  "Tap the share button": "Toque el botón de compartir",
  "then \"Add to Home Screen\" to install.": "y luego \"Agregar a pantalla de inicio\" para instalarla.",
  "Add Village Without Borders to your home screen for quick access.": "Ponga Village Without Borders en su pantalla de inicio para abrirla rápido.",
  "Install": "Instalar",
  "Keep your private messages safe.": "Proteja sus mensajes privados.",
  "If you clear your browser or get a new phone, old messages can't be opened. A recovery key brings them back.": "Si borra los datos del navegador o cambia de teléfono, no se podrán abrir los mensajes viejos. Una clave de recuperación los trae de vuelta.",
  "No problem. {name} will not be told why.": "No hay problema. No se le dirá a {name} por qué.",
