  'Invite sent. {name} will get a notice and can say yes or no.': 'Invitación enviada. {name} recibirá un aviso y puede decir que sí o que no.',
  '{name} is already in this village.': '{name} ya está en esta aldea.',
  '{name} was removed from this village before, so they cannot be invited.': 'Antes sacaron a {name} de esta aldea, así que no se le puede invitar.',
  '{name} said no to an invite here recently. You can try again in a few weeks.': '{name} dijo que no a una invitación aquí hace poco. Puede intentar otra vez en unas semanas.',
  'We could not find that person.': 'No encontramos a esa persona.',
  '{name} lives in this village’s area, so they can join on their own from Find a village.': '{name} vive en la zona de esta aldea, así que puede unirse por su cuenta desde Buscar una aldea.',
  'Only full members can invite guests.': 'Solo los miembros completos pueden invitar a otros.',
  'Could not load the list. Try again.': 'No se pudo cargar la lista. Intente otra vez.',
  'They can now pin announcements.': 'Ahora puede fijar anuncios.',
  'They are no longer a helper.': 'Ya no es ayudante.',
  'Hand this village to {name}? They will keep it from now on. You stay a member.': '¿Pasar esta aldea a {name}? Desde ahora será su Guardián. Usted sigue siendo miembro.',
  'Done. {name} now keeps this village.': 'Listo. Ahora {name} es Guardián de esta aldea.',
  'Pick a reason first.': 'Primero elija una razón.',
  'They were removed from this chat.': 'Se le sacó de este chat.',
  'Asked. It takes a second member to agree. They are not told.': 'Pedido. Hace falta que otro miembro esté de acuerdo. A esa persona no se le avisa.',
  'Agree to remove this person from the village chat? Only agree if you have seen a real reason.': '¿Está de acuerdo en sacar a esta persona del chat de la aldea? Solo diga que sí si ha visto una razón real.',
  'Could not take that back. Try again.': 'No se pudo retirar. Intente otra vez.',
  'People in {name}': 'Gente en {name}',
  'Close the list of people': 'Cerrar la lista de gente',
  'Tap a name to open their profile. Tap the arrow to vouch for them or ask to remove them. A vouch means you trust them. It does not guarantee they are safe.': 'Toque un nombre para abrir su perfil. Toque la flecha para responder por esa persona o pedir que la saquen. Responder por alguien significa que usted confía en esa persona. No garantiza que sea de confianza.',
  'You keep this village. You can pin announcements, name up to 2 helpers, or hand it to someone else. Open a name to do that.': 'Usted es Guardián de esta aldea. Puede fijar anuncios, nombrar hasta 2 ayudantes, o pasarla a otra persona. Abra un nombre para hacerlo.',
  'A second member is needed': 'Hace falta otro miembro',
  'A member asked to remove this person:': 'Un miembro pidió sacar a esta persona:',
