  'You are a guest here.': 'Usted es invitado aquí.',
  'You can read and post. Only full members can invite guests.': 'Puede leer y escribir. Solo los miembros completos pueden invitar a otros.',
  'Invite a guest': 'Invitar a alguien',
  'Invite someone you know who lives outside this village. They get a Guest badge, everyone here sees that they joined, and they cannot invite others.': 'Invite a alguien que conoce y que vive fuera de esta aldea. Tendrá una insignia de Invitado, todos aquí verán que se unió, y no podrá invitar a otros.',
  'Search people you know': 'Buscar gente que conoce',
