  'Villages overlap where they share zip codes. A gold line joins sister villages. A dotted path means neighbors from two villages have met in person. Tap your village to step inside.': 'Las aldeas se cruzan donde comparten códigos postales. Una línea dorada une a las aldeas hermanas. Un camino de puntos quiere decir que vecinos de dos aldeas se conocieron en persona. Toque su aldea para entrar.',
  'Your village is your neighbors by zip code. Type your zip code to join. It takes a minute.': 'Su aldea son sus vecinos según el código postal. Escriba su código postal para unirse. Toma un minuto.',
  'Emergency crews help when disaster hits. Tap your crew to see who is ready and what you bring.': 'Los equipos de emergencia ayudan cuando llega un desastre. Toque su equipo para ver quién está listo y qué lleva usted.',
  'You are not in a crew yet. Emergency crews help when disaster hits. Tap one to see what it does.': 'Todavía no está en un equipo. Los equipos de emergencia ayudan cuando llega un desastre. Toque uno para ver lo que hace.',
  'No crews yet. Emergency crews help when disaster hits. You can start one.': 'Todavía no hay equipos. Los equipos de emergencia ayudan cuando llega un desastre. Usted puede formar uno.',
  'Groups are people working together, not places. A gold line joins two that chose to connect.': 'Los grupos son gente trabajando junta, no lugares. Una línea dorada une a dos que decidieron conectarse.',
  'You do not belong to a group yet. Tap one to see what it does.': 'Todavía no es parte de un grupo. Toque uno para ver lo que hace.',
  'Find my village': 'Buscar mi aldea',
  'See emergency crews': 'Ver equipos de emergencia',
  'Back to groups': 'Volver a los grupos',
  'Find a village by zip code or town': 'Buscar una aldea por código postal o pueblo',
  'See every crew': 'Ver todos los equipos',
  'Every village': 'Todas las aldeas',
  'Every crew': 'Todos los equipos',
  'Every group': 'Todos los grupos',
  'If your zip code is not in this village, you can join as a guest when a member invites you or when it becomes a sister of your village.': 'Si su código postal no está en esta aldea, puede unirse como invitado cuando un miembro le invite o cuando se vuelva hermana de su aldea.',
  '{a} and {b}': '{a} y {b}',
  'These are sister villages. They share a Sister Campfire. Anyone in either village can join it.': 'Estas son aldeas hermanas. Comparten una Fogata hermana. Cualquiera de las dos aldeas puede unirse.',
  'These groups are connected. Their Heads and organizers share a Campfire. Find it under Cottage Chats and Campfires in Messages.': 'Estos grupos están conectados. Sus Líderes y organizadores comparten una Fogata. Búsquela en Chats de la casita y Fogatas, en Mensajes.',
  'Back to the globe': 'Volver al globo',
  'Please sign in first.': 'Por favor, primero entre a su cuenta.',
  'We could not find your profile. Try again in a moment.': 'No encontramos su perfil. Intente otra vez en un momento.',
  'Add your zip code on your Profile first, so we can find villages near you.': 'Primero ponga su código postal en su Perfil, para que podamos encontrar aldeas cerca de usted.',
  'A village already centers on your zip code. Find it on the World map and join that one.': 'Ya hay una aldea con centro en su código postal. Búsquela en el mapa del Mundo y únase a esa.',
  'You already started 3 villages. Ask an admin if one needs changes.': 'Ya empezó 3 aldeas. Pida a un administrador de VWB si una necesita cambios.',
  'One of those zip codes was not found. Try again.': 'No se encontró uno de esos códigos postales. Intente otra vez.',
  'A village can have up to 40 zip codes. Untick a few and try again.': 'Una aldea puede tener hasta 40 códigos postales. Quite algunos e intente otra vez.',
  'New accounts can join a village right away. Starting one opens up after your first 14 days, or sooner once a neighbor vouches for you or you finish a task with someone.': 'Las cuentas nuevas pueden unirse a una aldea enseguida. Empezar una se abre después de sus primeros 14 días, o antes si un vecino responde por usted o si termina una tarea con alguien.',
  'We could not open that village. Find it on the World map.': 'No pudimos abrir esa aldea. Búsquela en el mapa del Mundo.',
  'We could not load nearby zip codes. Try again.': 'No pudimos cargar los códigos postales cercanos. Intente otra vez.',
  'Could not check that. Try again in a moment.': 'No se pudo revisar. Intente otra vez en un momento.',
  'A village already centers on your zip code ({zip}). There can be only one village for each center. Join that one from the list above.': 'Ya hay una aldea con centro en su código postal ({zip}). Solo puede haber una aldea por cada centro. Únase a esa desde la lista de arriba.',
  'Could not start a village. Try again.': 'No se pudo empezar una aldea. Intente otra vez.',
  'We send one notification after the chat goes quiet, not one for every message. You can change this any time in the Village Square settings.': 'Mandamos un solo aviso cuando el chat se calma, no uno por cada mensaje. Puede cambiar esto cuando quiera en los ajustes de la Plaza de la aldea.',
  'Join or start a village': 'Unirse a una aldea o empezar una',
  'A village chat is for neighbors in the zip codes it covers. Anyone with an account can join a village that has their zip code. You can join more than one, especially where villages overlap. Any neighbor can start one.': 'El chat de una aldea es para los vecinos de los códigos postales que cubre. Cualquiera con una cuenta puede unirse a una aldea que tenga su código postal. Puede unirse a más de una, sobre todo donde las aldeas se cruzan. Cualquier vecino puede empezar una.',
  'See villages near you': 'Ver aldeas cerca de usted',
  'Add your zip code first': 'Primero ponga su código postal',
  'Your zip code is how we find villages near you. We never show it to anyone.': 'Con su código postal encontramos aldeas cerca de usted. Nunca se lo mostramos a nadie.',
  'No village covers your zip code yet. You can start one below.': 'Todavía no hay aldea que cubra su código postal. Puede empezar una aquí abajo.',
  'Start a village for your area': 'Empezar una aldea para su zona',
  'Do not see your town?': '¿No ve su pueblo?',
  'Any neighbor can start a village. You choose the name and the zip codes it covers. The admins are told when a new one starts.': 'Cualquier vecino puede empezar una aldea. Usted elige el nombre y los códigos postales que cubre. A los administradores de VWB se les avisa cuando empieza una nueva.',
  'Village name': 'Nombre de la aldea',
  'Leave blank to use your town': 'Déjelo en blanco para usar su pueblo',
  'Zip codes near {zip}. Tick the ones this village covers. Your own zip code stays on the list.': 'Códigos postales cerca de {zip}. Marque los que cubre esta aldea. Su propio código postal se queda en la lista.',
  'Show zip codes within': 'Mostrar códigos postales a menos de',
  'Zip codes: {n} of {total} ticked (tap to change)': 'Códigos postales: {n} de {total} marcados (toque para cambiar)',
  'Tick all': 'Marcar todos',
  'Untick all but mine': 'Quitar todos menos el mío',
  '{n} mi': '{n} mi',
  'yours': 'el suyo',
  'A village can have up to 40 zip codes.': 'Una aldea puede tener hasta 40 códigos postales.',
  'your new village chat': 'el chat de su nueva aldea',

