  'Sister Campfire. Anyone in either village can join. Members only, not scrambled. Messages delete after 30 days.': 'Fogata hermana. Cualquiera de las dos aldeas puede unirse. Solo para miembros, no cifrada. Los mensajes se borran después de 30 días.',
