  'About': 'Acerca de',
  'Announcements are open for every member to read, and only Ambassadors and admins can post there. Village chats are for neighbors near you. Anyone with an account can join, and there is no limit on size. You can join more than one. New members only see what is said after they join. Only people who joined a village chat can read it, and VWB admins cannot open village chats. Everyone in a chat can read it, so keep sensitive details out.': 'Todos los miembros pueden leer los Anuncios, y solo los Embajadores y los administradores de VWB pueden escribir ahí. Los chats de las aldeas son para los vecinos cerca de usted. Cualquiera con una cuenta puede unirse, y no hay límite de tamaño. Puede unirse a más de uno. Los miembros nuevos solo ven lo que se dice después de unirse. Solo la gente que se unió a un chat de la aldea puede leerlo, y los administradores de VWB no pueden abrir los chats de las aldeas. Todos en un chat pueden leerlo, así que no ponga detalles delicados.',
