  'Only people with a VWB account can see your {kind}, its resources and its events. Nothing shows to the public or on the website.': 'Solo la gente con una cuenta de VWB puede ver su {kind}, sus recursos y sus eventos. Nada aparece al público ni en el sitio web.',
