  "You now keep {village}": "Ahora usted cuida {village}",
  "You can pin announcements and name up to 2 helpers. You can hand the village to someone else any time.": "Puede fijar anuncios y nombrar hasta 2 ayudantes. Puede pasarle la aldea a otra persona cuando quiera.",
  "Your request for {skill} closes in about an hour. Tap to keep it open or close it.": "Su pedido de {skill} se cierra en más o menos una hora. Toque para dejarlo abierto o cerrarlo.",
  "Your request for {skill} (for {for}) closes in about an hour. Tap to keep it open or close it.": "Su pedido de {skill} (para {for}) se cierra en más o menos una hora. Toque para dejarlo abierto o cerrarlo.",
