  "Members, events, resources, needs, offers and decisions. No chats. Ask your Heads if you have questions.": "Miembros, eventos, recursos, necesidades, ofrecimientos y decisiones. Sin chats. Pregunte a sus Líderes si tiene dudas.",
  // Deciding together (Nov 7)
  "Yes, with a worry": "Sí, con una preocupación",
