  "We couldn't load the group's decisions. Try again.": "No pudimos cargar las decisiones del grupo. Intente otra vez.",
  "Say what you want to decide in a few words.": "Diga en pocas palabras qué quiere decidir.",
  "Your suggestion is up. Everyone in the group got an alert.": "Su sugerencia ya está publicada. Todos en el grupo recibieron un aviso.",
  "Say why, so the group can work on it.": "Diga por qué, para que el grupo pueda trabajar en ello.",
  "Your answer is saved. You can change it until it closes.": "Su respuesta está guardada. Puede cambiarla hasta que se cierre.",
  "Take back \"{title}\"? It closes now and nothing is decided.": "¿Retirar \"{title}\"? Se cierra ahora y no se decide nada.",
  "Saved. New decisions use this.": "Guardado. Las decisiones nuevas usan esto.",
  "Yes: {a}. Yes, with a worry: {c}. No: {b}.": "Sí: {a}. Sí, con una preocupación: {c}. No: {b}.",
