  "We decide by consensus. It passes when no one says no and at least 2 people say yes.": "Decidimos por consenso. Se aprueba cuando nadie dice que no y al menos 2 personas dicen que sí.",
  "Deciding together": "Decidir juntos",
  "At least 3 people need to answer. No names are shown, not even to leaders.": "Al menos 3 personas tienen que responder. No se muestran nombres, ni siquiera a los líderes.",
