  "Anything you can share?": "¿Tiene algo que pueda compartir?",
  "Even listening counts. Pick anything you are happy to do. Neighbors who need that kind of help can find you. You can change this any time.": "Hasta escuchar cuenta. Elija lo que le guste hacer. Los vecinos que necesiten ese tipo de ayuda lo pueden encontrar. Puede cambiar esto cuando quiera.",
  "Pick what I can share": "Elegir lo que puedo compartir",
  "Even listening counts.": "Hasta escuchar cuenta.",
  "Show the details on our group page": "Mostrar los detalles en la página de nuestro grupo",
  "Anyone on VWB can read them there. Only say what is needed, like \"diapers, size 4, 2 packs\". Never who it is for, where to bring it, or anything about health, family, or legal matters. Left off, the page shows only the kind of help.": "Cualquier persona en VWB los puede leer allí. Diga solo lo que se necesita, como \"pañales, talla 4, 2 paquetes\". Nunca para quién es, adónde llevarlo, ni nada sobre salud, familia o asuntos legales. Si lo deja sin marcar, la página solo muestra el tipo de ayuda.",
  "Your offer has been sent! You can see it, or take it back, in Your tasks.": "¡Su ofrecimiento fue enviado! Puede verlo, o retirarlo, en Sus tareas.",
  "This is your own request.": "Este es su propio pedido.",
  "This need is not open anymore.": "Esta necesidad ya no está abierta.",
