  "Names and member lists are private. Only its leaders can see or change them.": "Los nombres y las listas de miembros son privados. Solo sus líderes los pueden ver o cambiar.",
  "Each village has its own village chat, run by its Keeper and Helpers. Everyone has one home village, from the zip code on their profile. They join its chat after agreeing to a risk warning. Other villages they join, or are invited to, they visit as guests (guests read and post, but cannot be Keeper or Helper). New members only see messages from after they joined. Two members can remove someone, and admins can too. Any neighbor can start a village (up to 3 each, up to 40 zip codes). You can edit any village’s zip list here. Open People and leaders on a village to see who is in it, ask someone to be Keeper, or put people in the chat.": "Cada aldea tiene su propio chat, a cargo de su Guardián y sus Ayudantes. Cada persona tiene una aldea de casa, según el código postal de su perfil. Entra a su chat después de aceptar un aviso de riesgo. A otras aldeas a las que se une, o a las que la invitan, entra como visita (las visitas leen y escriben, pero no pueden ser Guardián ni Ayudante). Los miembros nuevos solo ven los mensajes de después de que entraron. Dos miembros pueden sacar a alguien, y los administradores también. Cualquier vecino puede empezar una aldea (hasta 3 cada uno, hasta 40 códigos postales). Aquí usted puede cambiar la lista de códigos postales de cualquier aldea. Abra Personas y líderes en una aldea para ver quién está, pedirle a alguien que sea Guardián, o poner personas en el chat.",
